head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS05600.xml";
scwin.processGp;
scwin.vRowCount = 0;
scwin.vDtlRowCount = 0;
scwin.vUsrGrpid;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 매출기관그룹 및 매출기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var param = '';

    //매출기관그룹조회		
    var dsNm = 'BNS_PACK_SALE_INST';
    var qryId = 'lds.stf.bnspack.select.listGrpSaleInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_GrpSaleInst, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);

    //매출기관조회
    param += "&{P}V_BND_CLSS_CD=";
    param += "&{P}V_BND_INST_CD=";
    param += "&{P}V_GRP_SCH_YN=Y";
    var qryId = 'lds.stf.bnspack.select.listSaleInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SaleInst, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_Delete
 * 설명       : 매출기관그룹을 삭제한다.
 ***********************************************/
scwin.fn_Delete = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "삭제"))) return;

    //임시데이터셋정의
    dts_Temp.removeAll();
    dts_Temp.insertRow();

    //삭제
    var url = "/bns/SaleInstMgt.do?method=deleteGrp";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var param = "USR_GRP_ID=" + scwin.vUsrGrpid;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Create
 * 설명       : 매출기관그룹을 등록한다.
 ***********************************************/
scwin.fn_Create = function() {
    if (!$c.cp.isModified(dts_SaleInst)) return;
    if ($c.stf.getObjectValue(txb_UsrGrpNm) == '') {
        $c.win.alert('그룹명을 입력 하십시오.');
        return;
    }
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_UsrGrpNm, 80, '그룹명')) return false;
    if (!$c.bns.fn_IsChecked(dts_SaleInst, '')) {
        $c.win.alert('그룹목록를 체크하십시오.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "그룹등록"))) return;
    var url = "/bns/SaleInstMgt.do?method=createGrpNew";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "USR_GRP_NM=" + $c.stf.getObjectValue(txb_UsrGrpNm);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo);
    $c.bns.BnsPanelToGroupBox(pnl_Input);

    //임시데이터셋정의

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

    //목록,상세조회
    scwin.fn_Search();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == SCREN_PROCS_TP_CD_02) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "그룹등록"));
    }
    if (scwin.processGp == SCREN_PROCS_TP_CD_04) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.fn_Search();
};
scwin.btn_Create_onclick = function() {
    if (scwin.vDtlRowCount == 0) return;
    scwin.processGp = SCREN_PROCS_TP_CD_02;
    scwin.fn_Create();
};
scwin.dts_GrpSaleInst_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_GrpSaleInst_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_SaleInst_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_SaleInst_OnLoadCompleted = function(rowcount) {
    scwin.vDtlRowCount = rowcount;
    //CloseWin(rowcount, grd_DtlList);

};
scwin.btn_Delete_onclick = function() {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = SCREN_PROCS_TP_CD_04;
    scwin.fn_Delete();
};
scwin.dts_GrpSaleInst_OnRowPosChanged = function(row) {
    scwin.vUsrGrpid = dts_GrpSaleInst.getCellData(row, "USR_GRP_ID");
};
